CREATE TYPE "UserRole" AS ENUM ('STUDENT','STAFF','ADMIN');
ALTER TABLE "User" ADD COLUMN "role" "UserRole" NOT NULL DEFAULT 'STUDENT', ADD COLUMN "username" TEXT, ADD COLUMN "displayUsername" TEXT, ADD COLUMN "studentNumber" TEXT, ADD COLUMN "avatarAttachmentId" TEXT;
UPDATE "User" SET role='ADMIN' WHERE "isAdmin"=true;
UPDATE "User" SET role='STAFF',"accountType"='STAFF' WHERE "isAdmin"=false AND EXISTS (SELECT 1 FROM "DepartmentMembership" m WHERE m."userId"="User".id);
UPDATE "User" SET "emailVerified"=true;
CREATE UNIQUE INDEX "User_username_key" ON "User"(username);
CREATE UNIQUE INDEX "User_studentNumber_key" ON "User"("studentNumber");
CREATE UNIQUE INDEX "User_avatarAttachmentId_key" ON "User"("avatarAttachmentId");
CREATE TABLE "ActivityNote" (id TEXT PRIMARY KEY,"activityId" TEXT NOT NULL,"authorId" TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ActivityNote_activityId_createdAt_id_idx" ON "ActivityNote"("activityId","createdAt",id);
ALTER TABLE "ActivityNote" ADD CONSTRAINT "ActivityNote_activityId_fkey" FOREIGN KEY ("activityId") REFERENCES "Activity"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ActivityNote" ADD CONSTRAINT "ActivityNote_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Attachment" ALTER COLUMN "ticketId" DROP NOT NULL, ADD COLUMN "noteId" TEXT, ADD COLUMN "avatarOwnerId" TEXT, ADD COLUMN "durationSeconds" DOUBLE PRECISION, ADD COLUMN waveform JSONB;
ALTER TABLE "Attachment" ADD CONSTRAINT "Attachment_noteId_fkey" FOREIGN KEY ("noteId") REFERENCES "ActivityNote"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Attachment" ADD CONSTRAINT "Attachment_avatarOwnerId_fkey" FOREIGN KEY ("avatarOwnerId") REFERENCES "User"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "User" ADD CONSTRAINT "User_avatarAttachmentId_fkey" FOREIGN KEY ("avatarAttachmentId") REFERENCES "Attachment"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE INDEX "Attachment_noteId_idx" ON "Attachment"("noteId");
CREATE INDEX "Attachment_avatarOwnerId_scanStatus_idx" ON "Attachment"("avatarOwnerId","scanStatus");
ALTER TABLE "Attachment" ADD CONSTRAINT "Attachment_context_check" CHECK (("ticketId" IS NOT NULL AND "avatarOwnerId" IS NULL) OR ("ticketId" IS NULL AND "avatarOwnerId" IS NOT NULL AND "messageId" IS NULL AND "noteId" IS NULL));
INSERT INTO "AuditLog" (id,action,metadata) VALUES (gen_random_uuid()::text,'THREE_ROLE_MIGRATION','{"existingProvisionedAccountsPreserved":true,"existingAccountsMarkedVerified":true}'::jsonb);
